<?php if(!defined('APP_ENTRY'))exit;
if($user['role']==='staff'){if($_SERVER['REQUEST_METHOD']==='POST')deny();$q='%'.search_term().'%';$data=rows('SELECT s.id,s.name,s.year_level,co.course_name FROM students s JOIN courses co ON co.id=s.course_id WHERE s.name LIKE ? OR co.course_name LIKE ? ORDER BY s.name',[$q,$q]);$columns=['id'=>'ID','name'=>'Student','course_name'=>'Course','year_level'=>'Year'];$heading='Student directory (read only)';require __DIR__.'/../includes/read_table.php';return;}
if($user['role']==='teacher'){ if($_SERVER['REQUEST_METHOD']==='POST')deny(); $q='%'.search_term().'%'; $data=rows('SELECT DISTINCT s.id,s.name,co.course_name,c.class_name FROM students s JOIN enrollments en ON en.student_id=s.id JOIN classes c ON c.id=en.class_id JOIN courses co ON co.id=s.course_id WHERE c.teacher_id=? AND (s.name LIKE ? OR c.class_name LIKE ?) ORDER BY s.name',[$user['id'],$q,$q]); $columns=['id'=>'ID','name'=>'Student','course_name'=>'Course','year_level'=>'Year','class_name'=>'Class']; require __DIR__.'/../includes/read_table.php'; return; }
$table='students';$entity='student';$heading='All students';$courses=array_column(rows('SELECT id,course_name FROM courses ORDER BY course_name'),'course_name','id');
$fields=['name'=>['label'=>'Full name','max'=>100],'email'=>['label'=>'Email','type'=>'email','max'=>100],'age'=>['label'=>'Age','type'=>'number'],'course_id'=>['label'=>'Course','options'=>$courses],'year_level'=>['label'=>'Year level','options'=>[1=>'First year',2=>'Second year',3=>'Third year',4=>'Fourth year'],'optional'=>true],'address'=>['label'=>'Address','max'=>255],'contact_number'=>['label'=>'Contact number','max'=>20],'gender'=>['label'=>'Gender','options'=>['Male'=>'Male','Female'=>'Female','Other'=>'Other']]];
$validate=function($id){$email=text_field('email',100,'Email');if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new DomainException('Enter a valid email.');$age=id_field('age');if($age>120)throw new DomainException('Age must be 1–120.');$gender=post('gender');if(!in_array($gender,['Male','Female','Other'],true))throw new DomainException('Select a gender.');$contact=text_field('contact_number',20,'Contact number');if(!preg_match('/^[0-9+ ()-]{7,20}$/D',$contact))throw new DomainException('Enter a valid contact number.');$year=post('year_level');if($year!==''&&!in_array($year,['1','2','3','4'],true))throw new DomainException('Invalid year level.');return ['year_level'=>$year===''?null:(int)$year,'name'=>text_field('name',100,'Name'),'email'=>$email,'age'=>$age,'course_id'=>id_field('course_id'),'address'=>text_field('address',255,'Address'),'contact_number'=>$contact,'gender'=>$gender];};
$listSql='SELECT s.id,s.name,s.email,s.age,s.gender,s.year_level,c.course_name FROM students s JOIN courses c ON c.id=s.course_id WHERE s.name LIKE ? OR s.email LIKE ? ORDER BY s.id';$columns=['id'=>'ID','name'=>'Name','email'=>'Email','age'=>'Age','gender'=>'Gender','year_level'=>'Year','course_name'=>'Course'];require __DIR__.'/../includes/admin_crud.php';
